class ApiKeysResource(Resource):
    """API key and permission management."""

    def list_permissions(self) -> Any:
        """List assignable API key permissions (auth, preauth, postauth, refund, bin-check, installment-query).  `GET /permissions`  Auth: Bearer."""
        return self._client.request("GET", "/permissions")

    def create_api_key(self, body: Mapping[str, Any]) -> Any:
        """Create an API key (body: name, permissions).  `POST /api_keys/`  Auth: Bearer."""
        return self._client.request("POST", "/api_keys/", body=body)

    def retrieve_api_key(self, api_key_id: Any) -> Any:
        """Get an API key by id.  `GET /api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("GET", f"/api_keys/{path_param(api_key_id)}")

    def update_api_key(self, api_key_id: Any, body: Mapping[str, Any]) -> Any:
        """Update an API key.  `PUT /api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("PUT", f"/api_keys/{path_param(api_key_id)}", body=body)

    def delete_api_key(self, api_key_id: Any) -> Any:
        """Delete an API key.  `DELETE /api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("DELETE", f"/api_keys/{path_param(api_key_id)}")

    def add_permission(self, api_key_id: Any, query: Optional[Mapping[str, Any]] = None) -> Any:
        """Add a permission to an API key (query: permission_id).  `POST /api_keys/{api_key_id}/permissions/`  Auth: Bearer."""
        return self._client.request("POST", f"/api_keys/{path_param(api_key_id)}/permissions/", query=query)

    def delete_permission(self, api_key_id: Any, permission_id: Any) -> Any:
        """Remove a permission from an API key.  `DELETE /api_keys/{api_key_id}/permissions/{permission_id}`  Auth: Bearer."""
        return self._client.request("DELETE", f"/api_keys/{path_param(api_key_id)}/permissions/{path_param(permission_id)}")

    def list_api_credentials(self, query: Optional[Mapping[str, Any]] = None) -> Any:
        """List the merchant's API keys (query: page, size, status=ACTIVE|PASSIVE, name).  `GET /api/merchant/v1/api-credentials`  Auth: Signed or Bearer."""
        return self._client.request("GET", "/api/merchant/v1/api-credentials", query=query)

    def retrieve_api_credential(self, api_key_id: Any) -> Any:
        """Get an API key by id (secret_key is not returned).  `GET /api/api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("GET", f"/api/api_keys/{path_param(api_key_id)}")

    def update_api_credential(self, api_key_id: Any, body: Mapping[str, Any]) -> Any:
        """Update an API key (body: name, is_active; secret_key is not returned).  `PUT /api/api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("PUT", f"/api/api_keys/{path_param(api_key_id)}", body=body)

    def delete_api_credential(self, api_key_id: Any) -> Any:
        """Delete an API key.  `DELETE /api/api_keys/{api_key_id}`  Auth: Signed or Bearer."""
        return self._client.request("DELETE", f"/api/api_keys/{path_param(api_key_id)}")


